kLen = input(7, "K Neighbors", 1, 15, 1)
featLen = input(20, "Feature Bars", 5, 30, 1)
histLen = input(200, "History Bars", 50, 400, 10)
marginThresh = input(0.43, "Margin Threshold", 0.05, 0.9, 0.01)
agreeThresh = input(0.35, "Agreement Max Disagreement", 0.05, 0.9, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

fRaw = (close - close[1]) / (abs(close[1]) + 0.000000001)
fCap = fRaw
if fCap > 0.05 {
    fCap := 0.05
}
if fCap < 0 - 0.05 {
    fCap := 0 - 0.05
}
f = fCap
if bar_index == 0 {
    f := 0.0
}

warmup = bar_index >= featLen + 10

bestDist = array()
bestLab = array()
ii = 0
while ii < kLen {
    array.push(bestDist, 999999.0)
    array.push(bestLab, 0)
    ii := ii + 1
}

bullVotes = 0
bearVotes = 0
M = 0.0
S = 1.0

if warmup {
    loopEnd = histLen
    if bar_index - featLen - 2 < histLen {
        loopEnd := bar_index - featLen - 2
    }
    if loopEnd < kLen + 1 {
        loopEnd := kLen + 1
    }
    i = featLen + 1
    while i <= loopEnd {
        dist2 = 0.0
        j = 0
        while j < featLen {
            diff = f[j] - f[i + j]
            dist2 := dist2 + diff * diff
            j := j + 1
        }
        dist = sqrt(dist2 + 0.000000000001)
        lbl = 0 - 1
        if close[i - 1] > close[i] { lbl := 1 }
        insertIdx = 0 - 1
        m = 0
        while m < kLen {
            if dist < bestDist[m] {
                insertIdx := m
                m := kLen
            }
            m := m + 1
        }
        if insertIdx >= 0 {
            m = kLen - 1
            while m > insertIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                m := m - 1
            }
            array.set(bestDist, insertIdx, dist)
            array.set(bestLab, insertIdx, lbl)
        }
        i := i + 1
    }
    bv = 0
    sv = 0
    m = 0
    while m < kLen {
        if bestDist[m] < 999998.0 {
            if bestLab[m] == 1 { bv := bv + 1 }
            else { sv := sv + 1 }
        }
        m := m + 1
    }
    bullVotes := bv
    bearVotes := sv
    tot = bv + sv
    if tot > 0 {
        M := (bv - sv) / tot
        S := 1.0 - abs(M)
    }
}

rng = high - low
bodyRatio = (close - open) / (rng + 0.000000001)
rngN = rng / (abs(close) + 0.000000001)
marginDyn = M + bodyRatio * 0.05
disagDyn = S + rngN * 2.0

buyCond = warmup and M > marginThresh and S < agreeThresh
sellCond = warmup and M < 0 - marginThresh and S < agreeThresh
buySig = buyCond and not buyCond[1]
sellSig = sellCond and not sellCond[1]

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 2, "separate")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize, 2, "separate")
}

plot(M, "Vote Margin", "#b48cff", 2, "separate")
plot(S, "Disagreement", "#ffd43b", 1, "separate")
plot3d(marginDyn, "Vote Margin Spine", "ribbon", "#b48cff", "separate", 0)
plot3d(disagDyn, "Disagreement Hull", "bars3d", "#ffd43b", "separate", 1)

// Volume Session Value Model
// Volume-profile-on-chart: POC + value area from visible session,
// price leaving value is the signal. 2D carries full info, 3D renders
// value as terrain rails with POC as labelled rail.

profileRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(200, "Session Length", 50, 500, 10)
showVA = input(true, "Show Value Area")
showPocLbl = input(true, "Show POC Rail Label")
useTerrain = input(true, "Use 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range (visible session = rolling loaded bars) ──────
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
rng = sessHigh - sessLow
if rng <= 0 { rng := close * 0.01 }
rowH = rng / profileRows

// ─── Build row volumes fresh each bar (plain assignment) ─────────
rowVol = array()
i = 0
while i < profileRows {
    array.push(rowVol, 0.0)
    i := i + 1
}

// Distribute each session bar's volume equally across overlapped rows
k = 0
while k < sessLen {
    bHigh = high[k]
    bLow = low[k]
    bVol = volume[k]
    if bHigh <= 0 { bHigh := close[k] }
    if bLow <= 0 { bLow := close[k] }
    if bHigh < bLow {
        t = bHigh
        bHigh := bLow
        bLow := t
    }
    rs = floor((bLow - sessLow) / rowH)
    re = floor((bHigh - sessLow) / rowH)
    if rs < 0 { rs := 0 }
    if re < 0 { re := 0 }
    if rs > profileRows - 1 { rs := profileRows - 1 }
    if re > profileRows - 1 { re := profileRows - 1 }
    nR = re - rs + 1
    if nR < 1 { nR := 1 }
    perRow = 0.0
    if bVol > 0 { perRow := bVol / nR }
    r = rs
    while r <= re {
        array.set(rowVol, r, array.get(rowVol, r) + perRow)
        r := r + 1
    }
    k := k + 1
}

totalVol = array.sum(rowVol)

// ─── Point of control: max row volume ────────────────────────────
pocRow = 0
pocVol = array.get(rowVol, 0)
i = 1
while i < profileRows {
    v = array.get(rowVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH
pocShare = 0.0
if totalVol > 0 { pocShare := pocVol / totalVol }

// ─── Value area: expand from POC outward ─────────────────────────
vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profileRows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(rowVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < profileRows - 1 { rightVal := array.get(rowVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < profileRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
    if vaLow == 0 and vaHigh == profileRows - 1 {
        guard := profileRows
    }
}
vahPrice = sessLow + (vaHigh + 0.5) * rowH
valPrice = sessLow + (vaLow + 0.5) * rowH
vaRange = vahPrice - valPrice
if vaRange <= 0 { vaRange := rowH }
valuePos = (close - valPrice) / vaRange

// ─── Signals: price leaving value / re-entering value ────────────
insideVA = close >= valPrice and close <= vahPrice
prevInside = close[1] >= valPrice[1] and close[1] <= vahPrice[1]
buySig = prevInside and close > vahPrice
sellSig = prevInside and close < valPrice
reenterSig = not prevInside and insideVA

// 3D terrain height: price-denominated value terrain centered on POC,
// scaled by POC dominance so terrain swells where value sits.
terrainOn = 1.0
if useTerrain == false { terrainOn := 0.0 }
terrainVal = pocPrice + (close - pocPrice) * pocShare * terrainOn + (vahPrice - valPrice) * 0.0
vaGate = 1.0
if showVA == false { vaGate := 0.0 }

if buySig {
    plotshape(bar_index, low, "Breakout Up", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Breakout Up", "coneup", "#22cc88", markerSize, 0, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Breakout Down", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Breakout Down", "conedown", "#ff4477", markerSize, 0, "3d")
}
if reenterSig {
    plotshape(bar_index, close, "Re-enter", "circle", "#ffd43b")
}

// POC rail label: only on newly established POC row (rare)
var wasPocRow = -1
if pocRow != wasPocRow and showPocLbl {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 0, "3d")
}
wasPocRow := pocRow

// ─── 2D: same information when 3D is off ─────────────────────────
plot(close, "Price", "#ffffff", 1)
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(valuePos * 100, "Value Position", "#4488ff", 1, "separate")
hline(100, "rgba(34,204,136,0.35)", "separate")
hline(0, "rgba(255,68,119,0.35)", "separate")

box.new(bar_index - sessLen, vahPrice, bar_index, valPrice, "#22cc88", "rgba(34,204,136,0.08)", 1, "vaBox")
text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "pocLbl")
text.new(bar_index, vahPrice, "VAH", "#22cc88", 1, "vahLbl")
text.new(bar_index, valPrice, "VAL", "#ff4477", 1, "valLbl")

if insideVA { bgcolor("rgba(34,204,136,0.04)") }
if buySig { bgcolor("rgba(34,204,136,0.10)") }
if sellSig { bgcolor("rgba(255,68,119,0.10)") }

// ─── 3D: value rails as terrain, POC as labelled rail ────────────
// line3d draws exact straight level segments; DISTINCT z_level per level.
plot3d(terrainVal, "Value Terrain", "surface", "#4488ff", "3d", 1)
plot3d(pocPrice, "POC", "line3d", "#ffd43b", "3d", 0)
plot3d(vahPrice, "VAH", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze at bar 0 — var initializers run once, must be plain assignment.
lvl = highest(high, 20)
// FIX 2: close[-1] is a future leak (lookahead) — corrected to current close > lvl, same breakout intent.
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine syntax — OakScript uses (bar_index, price, title, "style", "#hex").
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
// FIX 4: oscillator RSI in pane="3d" renders as spiky forest over price — oscillators must use pane="separate".
plot(r, "RSI", "#b48cff")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowScale = input(0.1, "Flow Scale", 0.001, 1.0, 0.001)
critical_threshold = input(150.0, "Critical Threshold", 10.0, 500.0, 1.0)
spin_factor = input(0.5, "Spin Factor", 0.05, 3.0, 0.05)
max_rings = input(5.0, "Max Rings", 1.0, 5.0, 1.0)
ring_expansion_rate = input(1.0, "Ring Expansion Rate", 0.1, 5.0, 0.1)
ring_max_radius = input(10.0, "Ring Max Radius", 2.0, 20.0, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = abs(close - open) / (close + 0.000000001) * volume * flowScale
spin_speed = spin_factor * flow_psi
locked = flow_psi > critical_threshold
overSig = locked and not locked[1]
releaseSig = not locked and locked[1]

var disc_angle = 0.0
var lockBars = 0.0

if locked {
    lockBars := lockBars[1] + 1
} else {
    lockBars := 0
}

if locked {
    disc_angle := disc_angle[1]
} else {
    disc_angle := disc_angle[1] + spin_speed
}

if disc_angle > 360 {
    disc_angle := disc_angle - 360
}
if disc_angle < 0 {
    disc_angle := disc_angle + 360
}

cycleLen = ring_max_radius / (ring_expansion_rate + 0.000000001)
spacing = cycleLen / 5.0
age0 = lockBars
age1 = lockBars - spacing
age2 = lockBars - spacing * 2.0
age3 = lockBars - spacing * 3.0
age4 = lockBars - spacing * 4.0
rad0 = 1.0 + ring_expansion_rate * age0
rad1 = 1.0 + ring_expansion_rate * age1
rad2 = 1.0 + ring_expansion_rate * age2
rad3 = 1.0 + ring_expansion_rate * age3
rad4 = 1.0 + ring_expansion_rate * age4
sz0 = 0.6 + rad0 * 0.2
sz1 = 0.6 + rad1 * 0.2
sz2 = 0.6 + rad2 * 0.2
sz3 = 0.6 + rad3 * 0.2
sz4 = 0.6 + rad4 * 0.2
show0 = locked and age0 >= 0 and rad0 < ring_max_radius
show1 = locked and age1 >= 0 and rad1 < ring_max_radius and max_rings >= 2
show2 = locked and age2 >= 0 and rad2 < ring_max_radius and max_rings >= 3
show3 = locked and age3 >= 0 and rad3 < ring_max_radius and max_rings >= 4
show4 = locked and age4 >= 0 and rad4 < ring_max_radius and max_rings >= 5
discPrice = close + flow_psi * 0.001
discTick = bar_index % 20 == 0
discShow = overSig or releaseSig or discTick

if overSig {
    plotshape(bar_index, high, "OVERPRESSURE", "triangledown", "#ff4477")
}
if releaseSig {
    plotshape(bar_index, low, "Release", "triangleup", "#22cc88")
}
if overSig {
    plotshape_3d(bar_index, high, "OVERPRESSURE", "conedown", "#ff4477", markerSize, 6, "separate")
}
if releaseSig {
    plotshape_3d(bar_index, low, "Release", "coneup", "#22cc88", markerSize, 6, "separate")
}
if discShow {
    plotshape_3d(bar_index, discPrice, "Disc", "torus", "#22aaff", 1.5, 0, "separate", 90, disc_angle, 0)
}
if show0 {
    plotshape_3d(bar_index, discPrice, "Ring0", "torus", "#ff4477", sz0, 1, "separate", 90, 0, 0)
}
if show1 {
    plotshape_3d(bar_index, discPrice, "Ring1", "torus", "#ff8833", sz1, 2, "separate", 90, 0, 0)
}
if show2 {
    plotshape_3d(bar_index, discPrice, "Ring2", "torus", "#ffcc33", sz2, 3, "separate", 90, 0, 0)
}
if show3 {
    plotshape_3d(bar_index, discPrice, "Ring3", "torus", "#ff8833", sz3, 4, "separate", 90, 0, 0)
}
if show4 {
    plotshape_3d(bar_index, discPrice, "Ring4", "torus", "#ff4477", sz4, 5, "separate", 90, 0, 0)
}
if overSig {
    label3d(bar_index, high + (high - low + 1.0) * 0.5, "OVERPRESSURE", "#ff4477", 2, 5, "separate")
}

plot(flow_psi, "flow_psi", "#22aaff", 2, "separate")
hline(critical_threshold, "#ff4477", "separate")
plot(spin_speed, "spin_speed", "#88ddff", 1, "separate")
plot3d(flow_psi, "Flow Pressure", "vortex", "#22aaff", "separate", 0)
plot3d(disc_angle + close * 0.001, "Disc Angle", "trail", "#ffaa22", "separate", 1)
